public class CnpjValidator {
    public static boolean validate(String cnpj) {
        if (cnpj == null || !cnpj.matches("\\d{14}") || cnpj.matches("(\\d)\\1{13}")) {
            return false;
        }
        int d1 = calcDigit(cnpj.substring(0, 12), new int[]{5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2});
        int d2 = calcDigit(cnpj.substring(0, 13), new int[]{6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2});
        return d1 == Character.getNumericValue(cnpj.charAt(12)) && d2 == Character.getNumericValue(cnpj.charAt(13));
    }
    private static int calcDigit(String s, int[] weights) {
        int sum = 0;
        for (int i = 0; i < s.length(); i++) {
            sum += Character.getNumericValue(s.charAt(i)) * weights[i];
        }
        int remainder = sum % 11;
        return remainder < 2 ? 0 : 11 - remainder;
    }
}

