package main

import (
	"regexp"
	"strconv"
)

func ValidateCNPJ(cnpj string) bool {
	if matched, _ := regexp.MatchString(`^\d{14}$`, cnpj); !matched {
		return false
	}
	if matched, _ := regexp.MatchString(`^(\d)\1{13}$`, cnpj); matched {
		return false
	}
	calcDigit := func(s string, weights []int) int {
		sum := 0
		for i := 0; i < len(s); i++ {
			digit, _ := strconv.Atoi(string(s[i]))
			sum += digit * weights[i]
		}
		remainder := sum % 11
		if remainder < 2 {
			return 0
		}
		return 11 - remainder
	}
	w1 := []int{5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2}
	w2 := []int{6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2}
	d1 := calcDigit(cnpj[:12], w1)
	d2 := calcDigit(cnpj[:13], w2)
	lastD12, _ := strconv.Atoi(string(cnpj[12]))
	lastD13, _ := strconv.Atoi(string(cnpj[13]))
	return d1 == lastD12 && d2 == lastD13
}

