pub fn validate_cnpj(cnpj: &str) -> bool {
    if cnpj.len() != 14 || !cnpj.chars().all(|c| c.is_ascii_digit()) {
        return false;
    }
    if cnpj.chars().all(|c| c == cnpj.chars().next().unwrap()) {
        return false;
    }
    let digits: Vec<u32> = cnpj.chars().map(|c| c.to_digit(10).unwrap()).collect();
    let calc_digit = |slice: &[u32], weights: &[u32]| -> u32 {
        let sum: u32 = slice.iter().zip(weights.iter()).map(|(&d, &w)| d * w).sum();
        let remainder = sum % 11;
        if remainder < 2 { 0 } else { 11 - remainder }
    };
    let w1 = [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
    let w2 = [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
    let d1 = calc_digit(&digits[0..12], &w1);
    let d2 = calc_digit(&digits[0..13], &w2);
    d1 == digits[12] && d2 == digits[13]
}
